"""PCAP to PDML converter library.

.. deprecated:: 1.2.8
    This library is deprecated and will be removed in a future release.
    Please use ``taf.converters.tshark`` library instead.
"""

import logging
from taf.converters.pcaptopdml.factory import PcapToPdmlFactory
from taf.converters.base import base

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class pcaptopdml(base):
    """PCAP to PDML converter.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_pcap_to_pdml_converter(self, name, file_path_pattern, tshark_path=None,
                                      luashark_path=None,
                                      command_template=None):
        """
        Creates a Converter for pcap to pdml file conversion.

        :param str name: name of the converters
        :param str file_path_pattern: file paths (wildcards allowed, eg: x/y/z/*.pcap or x/*/z/*.pcap )
        :param str command_template: Command template of Pcap to pdml conversion(optional), default command template
                                     will use luashark_path if mcshark plugin is not installed, else it will ignore
                                     luashark_path parameter.
        :param str tshark_path: Path of tshark executable
        :param str luashark_path: Path of luashark file, not applicable if mcshark plugin is available
                                  (default value is /opt/luashark/luashark.lua)

.. code-block:: robotframework

        *** Settings ***
        Library      taf.converters.pcaptopdml    WITH NAME    pcaptopdml

        *** Test Cases ***
        Convert_PCAP_file_to_PDML
            pcaptopdml.create_pcap_to_pdml_converter
            ...      name=converter
            ...      file_path_pattern=/home/ute/oamTcpdump/oamTcpdump.pcap
            pcaptopdml.convert    converter


        Convert_PCAP_file_to_PDML_with_filter
            pcaptopdml.create_pcap_to_pdml_converter
            ...      name=converter
            ...      file_path_pattern=/home/ute/oamTcpdump/oamTcpdump.pcap
            ...      command_template={tshark_path} -Y "x2ap" -r {input_file} -X lua_script:{luashark_path} -T pdml > {output_file}
            pcaptopdml.convert    converter

        """
        logging.warning(
            "taf.converters.pcaptopdml is deprecated and will be removed in a future release. "
            "Please use taf.converters.tshark library instead.",
            DeprecationWarning,
            stacklevel=2
        )
        logger.info("Creating Converter with alias name" + name)
        existing_arguments = {}
        configuration = {
            "file_path_pattern": file_path_pattern}
        if command_template is not None:
            configuration["command_template"] = command_template
        if tshark_path is not None:
            configuration["tshark_path"] = tshark_path
        if luashark_path is not None:
            configuration["luashark_path"] = luashark_path
        converter = PcapToPdmlFactory().create(configuration=configuration, existing_arguments=existing_arguments)
        logger.info(name + " converter created successfully")
        self.set_alias(name, converter)
